//
    /*
     * Theme toggle: cycles light -> dark -> linen -> fjord -> matte -> charcoal
     * -> paper, with the same Feather icons as django-react's ThemeIcons.
     * A page embedding this blog in an iframe can sync its theme with:
     *   iframe.contentWindow.postMessage({ theme: "dark" }, "*")
     */
    (function () {
      var root = document.documentElement;
      var button = document.getElementById("theme-toggle");
      var THEMES = window.THEMES;
      var ICONS = {
        light: '<circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42' +
          'M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/>',
        dark: '<path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>',
        linen: '<path d="M20.24 12.24a6 6 0 0 0-8.49-8.49L5 10.5V19h8.5z"/><path d="M16 8L2 22M17.5 15H9"/>',
        fjord: '<path d="M12 2.69l5.66 5.66a8 8 0 1 1-11.31 0z"/>',
        matte: '<path d="M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z"/>',
        charcoal: '<circle cx="12" cy="12" r="10"/><path d="M14.31 8l5.74 9.94M9.69 8h11.48' +
          'M7.38 12l5.74-9.94M9.69 16L3.95 6.06M14.31 16H2.83M16.62 12l-5.74 9.94"/>',
        paper: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>' +
          '<path d="M14 2v6h6M16 13H8M16 17H8M10 9H8"/>'
      };

      function name(t) {
        return t.charAt(0).toUpperCase() + t.slice(1);
      }

      function current() {
        var t = root.getAttribute("data-theme");
        return THEMES.indexOf(t) < 0 ? "light" : t;
      }

      function render() {
        var t = current();
        var next = THEMES[(THEMES.indexOf(t) + 1) % THEMES.length];
        var label = "Theme: " + name(t) + " (next: " + name(next) + ")";
        button.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true">' + ICONS[t] + "</svg>";
        button.title = label;
        button.setAttribute("aria-label", label);
      }

      function setTheme(t, save) {
        if (THEMES.indexOf(t) < 0) return;
        root.setAttribute("data-theme", t);
        if (save) {
          try { localStorage.setItem("theme", t); } catch (e) {}
        }
        render();
      }

      button.addEventListener("click", function () {
        setTheme(THEMES[(THEMES.indexOf(current()) + 1) % THEMES.length], true);
      });

      window.addEventListener("message", function (e) {
        if (e.data && typeof e.data.theme === "string") setTheme(e.data.theme, false);
      });

      render();
    })();
