//
    /*
     * Numbered pagination for Blogger.
     * Blogger only gives Newer/Older links, so we read the post feed,
     * work out where every page starts, and link to each page with the
     * same URL format Blogger uses: /search?updated-max=DATE&max-results=N
     * (updated-max is exclusive: the page shows posts published before DATE).
     *
     * The blog address and page type come from Blogger (data-np-* on <body>),
     * not from location, so it also works in the theme editor preview, in an
     * iframe on another site, and on custom domains. The feed is loaded with
     * JSONP, which works cross-origin.
     *
     * Home and label pages get page numbers. Everything else (posts, search,
     * archives) or a failed feed load gets plain ‹ › arrows built from
     * Blogger's own Newer/Older links.
     */
    (function () {
      var FEED_CHUNK = 150; // Blogger caps feed results per request
      var CACHE_MS = 5 * 60 * 1000;
      var body = document.body;
      var pager = document.getElementById("blog-pager");
      if (!pager) return;

      var params = new URLSearchParams(location.search);
      var home = body.getAttribute("data-np-home") || location.origin + "/";
      // Avoid mixed content when the page itself is on https.
      if (location.protocol === "https:") home = home.replace(/^http:/, "https:");
      if (home.charAt(home.length - 1) !== "/") home += "/";
      var pageType = body.getAttribute("data-np-type") || "";
      var label = body.getAttribute("data-np-label") || "";
      var query = body.getAttribute("data-np-query") || "";
      var mobile = params.get("m") === "1" ? "&m=1" : "";

      var labelPath = label ? encodeURIComponent(label) : "";
      var feedUrl = home + "feeds/posts/summary" + (label ? "/-/" + labelPath : "");
      var pageBase = home + "search" + (label ? "/label/" + labelPath : "");
      var perPage = parseInt(params.get("max-results"), 10) ||
        document.querySelectorAll(".post-outer").length;
      // "+" in the timezone may come back as a space if the URL wasn't encoded.
      var updatedMax = (params.get("updated-max") || "").replace(/ /g, "+");

      function el(tag, cls, text, attrs) {
        var e = document.createElement(tag);
        e.className = cls;
        e.textContent = text;
        for (var k in attrs || {}) e.setAttribute(k, attrs[k]);
        return e;
      }

      var CHEVRON = {
        prev: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 6l-6 6 6 6"/></svg>',
        next: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg>'
      };

      function arrow(nav, href, dir, rel, aria) {
        var a = href ?
          el("a", "np-arrow", "", { href: href, rel: rel, "aria-label": aria }) :
          el("span", "np-arrow np-disabled", "", { "aria-hidden": "true" });
        a.innerHTML = CHEVRON[dir];
        nav.appendChild(a);
      }

      function show(nav, info) {
        var old = pager.querySelectorAll(".np, .np-info");
        for (var i = 0; i < old.length; i++) pager.removeChild(old[i]);
        if (!nav) {
          pager.style.display = "none";
          return;
        }
        pager.style.display = "";
        if (pager.className.indexOf("np-ready") < 0) pager.className += " np-ready";
        pager.appendChild(nav);
        if (info) pager.appendChild(el("p", "np-info", info));
      }

      // Fallback: prev/next arrows from Blogger's own Newer/Older links.
      function renderArrows() {
        var newer = pager.querySelector("a.blog-pager-newer-link");
        var older = pager.querySelector("a.blog-pager-older-link");
        if (!newer && !older) return show(null);
        var item = pageType === "item" || pageType === "static_page";
        var nav = el("nav", "np", "", { "aria-label": "Pagination" });
        arrow(nav, newer && newer.href, "prev", "prev", item ? "Newer post" : "Newer posts");
        arrow(nav, older && older.href, "next", "next", item ? "Older post" : "Older posts");
        show(nav);
      }

      function readCache() {
        try {
          var c = JSON.parse(sessionStorage.getItem("np:" + feedUrl));
          if (c && Date.now() - c.t < CACHE_MS) return c.d;
        } catch (e) {}
        return null;
      }

      function writeCache(dates) {
        try {
          sessionStorage.setItem("np:" + feedUrl,
            JSON.stringify({ t: Date.now(), d: dates }));
        } catch (e) {}
      }

      function fetchDates(start, acc, ok, fail) {
        window.blogJsonp(feedUrl + "?alt=json-in-script&max-results=" + FEED_CHUNK +
          "&start-index=" + start, function (json) {
          try {
            var entries = json.feed.entry || [];
            var total = parseInt(json.feed.openSearch$totalResults.$t, 10);
            for (var i = 0; i < entries.length; i++) acc.push(entries[i].published.$t);
            if (entries.length === FEED_CHUNK && acc.length < total) {
              fetchDates(start + FEED_CHUNK, acc, ok, fail);
            } else {
              ok(acc);
            }
          } catch (e) {
            fail();
          }
        }, fail);
      }

      // Same format Blogger's own Older link uses: drop milliseconds.
      function stamp(published) {
        return published.replace(/\.\d+/, "");
      }

      function pageUrl(n, dates) {
        if (n === 1) {
          if (label) return pageBase + "?max-results=" + perPage + mobile;
          return home + (mobile ? "?m=1" : "");
        }
        var lastOfPrev = dates[(n - 1) * perPage - 1];
        return pageBase + "?updated-max=" + encodeURIComponent(stamp(lastOfPrev)) +
          "&max-results=" + perPage + mobile;
      }

      function currentPage(dates) {
        if (!updatedMax) return 1;
        var limit = Date.parse(updatedMax);
        if (isNaN(limit)) return 1;
        for (var i = 0; i < dates.length; i++) {
          if (Date.parse(dates[i]) < limit) return Math.floor(i / perPage) + 1;
        }
        return Math.ceil(dates.length / perPage);
      }

      // Always the same number of slots, so the bar keeps its width.
      function pageList(cur, last, siblings) {
        var out = [], p;
        var slots = siblings * 2 + 5; // first, gap, window, gap, last
        if (last <= slots) {
          for (p = 1; p <= last; p++) out.push(p);
        } else if (cur <= siblings + 3) {
          for (p = 1; p <= slots - 2; p++) out.push(p);
          out.push(null, last);
        } else if (cur >= last - siblings - 2) {
          out.push(1, null);
          for (p = last - slots + 3; p <= last; p++) out.push(p);
        } else {
          out.push(1, null);
          for (p = cur - siblings; p <= cur + siblings; p++) out.push(p);
          out.push(null, last);
        }
        return out;
      }

      function narrow() {
        return (pager.clientWidth || window.innerWidth) < 480 ? 1 : 2;
      }

      function renderNumbers(dates) {
        var last = Math.ceil(dates.length / perPage);
        if (last <= 1) return show(null);
        var cur = Math.min(currentPage(dates), last);
        var list = pageList(cur, last, narrow());
        var nav = el("nav", "np", "", { "aria-label": "Pagination" });

        arrow(nav, cur > 1 && pageUrl(cur - 1, dates), "prev", "prev", "Previous page");
        for (var i = 0; i < list.length; i++) {
          var n = list[i];
          if (n === null) {
            nav.appendChild(el("span", "np-gap", "\u2026", { "aria-hidden": "true" }));
          } else if (n === cur) {
            nav.appendChild(el("span", "np-current", String(n), { "aria-current": "page" }));
          } else {
            nav.appendChild(el("a", "np-num", String(n),
              { href: pageUrl(n, dates), "aria-label": "Page " + n }));
          }
        }
        arrow(nav, cur < last && pageUrl(cur + 1, dates), "next", "next", "Next page");
        show(nav, "Page " + cur + " of " + last);
      }

      var numbered = pageType === "index" && !query && perPage > 0;
      if (!numbered) return renderArrows();

      function start(dates) {
        renderNumbers(dates);
        var s = narrow(), timer;
        window.addEventListener("resize", function () {
          clearTimeout(timer);
          timer = setTimeout(function () {
            if (narrow() !== s) {
              s = narrow();
              renderNumbers(dates);
            }
          }, 150);
        });
      }

      var cached = readCache();
      if (cached) return start(cached);

      // Show arrows right away; swap in page numbers when the feed arrives.
      renderArrows();
      var gaveUp = false;
      var timeout = setTimeout(function () { gaveUp = true; }, 8000);
      fetchDates(1, [], function (dates) {
        clearTimeout(timeout);
        if (gaveUp) return;
        writeCache(dates);
        start(dates);
      }, function () {
        clearTimeout(timeout);
      });
    })();
